const scene=new THREE.Scene();const camera=new THREE.PerspectiveCamera(36,1,.1,100);const controls=new OrbitControls(camera,canvas);controls.enableDamping=true;controls.target.set(0,1.5,0);controls.minDistance=5;controls.maxDistance=13;controls.maxPolarAngle=Math.PI*.49;controls.enablePan=false;controls.autoRotateSpeed=.65;
