let seed=24;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}function mat(color,roughness=.8){return new THREE.MeshStandardMaterial({color,roughness})}const earth=mat(0x453427),gravel=mat(0x968e71),mossMats=[0x4f6c26,0x5d782d,0x73873a,0x405e24,0x7e8d42].map(c=>mat(c));
function mesh(geo,material,parent=scene){const m=new THREE.Mesh(geo,material);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}function ellipsoid(parent,material,x,y,z,sx,sy,sz){const m=mesh(new THREE.SphereGeometry(1,20,14),material,parent);m.position.set(x,y,z);m.scale.set(sx,sy,sz);return m}
