const pebbleGeo=new THREE.IcosahedronGeometry(1,1);for(let i=0;i<380;i++){const a=rand()*Math.PI*2,r=1.23+rand()*.08;const p=mesh(pebbleGeo,mat([0xbbb59b,0x7c7c68,0x9b947e,0xd0c6a8][i%4]));p.position.set(Math.cos(a)*r,.10+rand()*.16,Math.sin(a)*r);p.scale.set(.045+rand()*.06,.025+rand()*.04,.03+rand()*.04);p.rotation.set(rand()*3,rand()*3,rand()*3)}for(let i=0;i<170;i++){let a=rand()*6.28;const p=mesh(pebbleGeo,mat([0x62513b,0x7b6347,0x392e24][i%3]));p.position.set(Math.cos(a)*1.335,.34+rand()*.25,Math.sin(a)*1.335);p.scale.setScalar(.015+rand()*.026)}
