function leaf(length,width){const sh=new THREE.Shape();sh.moveTo(0,0);sh.bezierCurveTo(width*.6,length*.25,width*.7,length*.65,0,length);sh.bezierCurveTo(-width*.7,length*.65,-width*.6,length*.2,0,0);return new THREE.ShapeGeometry(sh)}
const leafGeo=leaf(1,.29);const ferns=[];function fern(x,z,s){const group=new THREE.Group();group.position.set(x,.68,z);group.scale.setScalar(s);for(let f=0;f<9;f++){const a=f/9*Math.PI*2+rand()*.3;const height=.7+rand()*.55;const reach=.35+rand()*.45;const points=[];for(let k=0;k<=16;k++){let t=k/16;points.push(new THREE.Vector3(Math.cos(a)*reach*t*t,height*(t-.25*t*t),Math.sin(a)*reach*t*t))}mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),24,.008,4,false),stemMat,group);for(let k=2;k<16;k++){const t=k/16,pos=points[k];const len=(.06+.26*Math.sin(t*Math.PI))*(1-.4*t);for(const sign of [-1,1]){const l=mesh(leafGeo,leafMats[(f+k)%4],group);l.position.copy(pos);l.scale.set(len,len,1);const direction=new THREE.Vector3(Math.cos(a+sign*1.05),.24,Math.sin(a+sign*1.05)).normalize();l.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),direction);l.rotateY(a);}}}scene.add(group);ferns.push(group)}
[[-.78,-.4,1.15],[.25,-.84,1.35],[.85,-.2,.94],[-1,.3,.73],[.61,.57,.65],[-.3,-.4,.9],[.95,.25,.8]].forEach(p=>fern(...p));
const deer=new THREE.Group();deer.position.set(0,.74,.45);deer.rotation.y=-.45;scene.add(deer);const ceramic=new THREE.MeshPhysicalMaterial({color:0xf0e7d0,roughness:.23,metalness:0,clearcoat:1,clearcoatRoughness:.16});ellipsoid(deer,ceramic,0,.35,0,.26,.18,.13);ellipsoid(deer,ceramic,.20,.56,0,.105,.24,.10).rotation.z=-.3;ellipsoid(deer,ceramic,.28,.75,0,.145,.11,.095);ellipsoid(deer,ceramic,.39,.71,.008,.09,.065,.07);for(let x of [-.17,.15])for(let z of [-.08,.08]){const leg=mesh(new THREE.CylinderGeometry(.037,.024,.31,12),ceramic,deer);leg.position.set(x,.155,z);leg.rotation.z=x<0?-.08:.08}ellipsoid(deer,ceramic,.20,.875,-.065,.045,.13,.027).rotation.z=.35;ellipsoid(deer,ceramic,.30,.88,.035,.041,.13,.025).rotation.z=-.32;ellipsoid(deer,ceramic,-.265,.4,0,.1,.052,.06).rotation.z=-.5;const dark=mat(0x3e352d,.3);ellipsoid(deer,dark,.32,.775,.084,.011,.012,.005);ellipsoid(deer,dark,.32,.775,-.084,.011,.012,.005);ellipsoid(deer,mat(0xa08b73),.46,.728,.005,.014,.019,.038);
