const glassGroup=new THREE.Group();scene.add(glassGroup);const profile=[[0,0],[1.16,0],[1.32,.08],[1.40,.22],[1.43,.5],[1.43,2.5],[1.4,2.8],[1.26,3.03],[1.12,3.13],[1.11,3.35],[1.15,3.4],[1.15,3.46],[1.09,3.47],[1.07,3.4],[1.075,3.14],[1.22,2.99],[1.35,2.78],[1.38,2.5],[1.38,.3],[1.3,.15],[0,.15]].map(p=>new THREE.Vector2(...p));const glassMat=new THREE.MeshPhysicalMaterial({color:0xe3efdf,transparent:true,opacity:.13,roughness:.09,metalness:.12,side:THREE.DoubleSide,depthWrite:false,clearcoat:1});const jar=mesh(new THREE.LatheGeometry(profile,128),glassMat,glassGroup);jar.castShadow=false;jar.renderOrder=5;
