for(const [a,w,opacity] of [[-.55,.055,.33],[2.9,.10,.38],[.1,.017,.24]]){const pts=[];for(let i=0;i<25;i++){const y=.38+i*.10;const r=y>2.7?1.43-(y-2.7)*.52:1.438;pts.push(new THREE.Vector3(Math.cos(a)*r,y,Math.sin(a)*r))}const strip=mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts),32,w,6,false),new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity,depthWrite:false}),glassGroup);strip.castShadow=false;strip.renderOrder=6}
function update(){const n=+document.querySelector('#moss').value; mossPatches.forEach((p,i)=>p.visible=i<n);document.querySelector('#moss-value').textContent=n<28?'Sparse':n<45?'Soft & green':n<58?'Lush':'Forest floor';const count=+document.querySelector('#ferns').value;ferns.forEach((f,i)=>f.visible=i<count);document.querySelector('#fern-value').textContent=`${count} ${count===1?'plant':'plants'}`;const p=+document.querySelector('#position').value;deer.position.x=p/100;document.querySelector('#position-value').textContent=p<-20?'Left of the path':p>20?'Right of the path':'In the clearing';}document.querySelectorAll('input').forEach(el=>el.addEventListener('input',update));update();
document.querySelector('#deer-toggle').onclick=e=>{deer.visible=!deer.visible;const b=e.currentTarget;b.classList.toggle('on',deer.visible);b.setAttribute('aria-pressed',deer.visible)};
document.querySelector('#rotate').onclick=e=>{controls.autoRotate=!controls.autoRotate;e.currentTarget.classList.toggle('active',controls.autoRotate);e.currentTarget.setAttribute('aria-pressed',controls.autoRotate)};document.querySelector('#reset').onclick=reset;document.querySelector('#top').onclick=()=>{camera.position.set(.01,8.8,.01);controls.target.set(0,.8,0);controls.update()};document.querySelector('#glass').onclick=e=>{glassGroup.visible=!glassGroup.visible;e.currentTarget.textContent=glassGroup.visible?'◈  Glass on':'◇  Glass off';e.currentTarget.setAttribute('aria-pressed',glassGroup.visible)};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(t=>t.classList.toggle('active',t===b));document.querySelector('#design-panel').hidden=b.dataset.tab!=='design';document.querySelector('#guide-panel').hidden=b.dataset.tab!=='guide'});
function download(url,name){const a=document.createElement('a');a.href=url;a.download=name;a.click()}function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}
document.querySelector('#save').onclick=()=>{renderer.render(scene,camera);const out=document.createElement('canvas');out.width=canvas.width;out.height=canvas.height;const ctx=out.getContext('2d');ctx.fillStyle='#e9ecdf';ctx.fillRect(0,0,out.width,out.height);ctx.drawImage(canvas,0,0);download(out.toDataURL('image/png'),'a-little-woodland-for-nan.png');toast('A little woodland, saved for later.')};document.querySelector('#download-plan').onclick=()=>{const text=`A little woodland for Nan\nBirthday terrarium design\n\nJar: approximately 20 cm wide × 28 cm tall, open apothecary jar\nMoss: ${document.querySelector('#moss-value').textContent}\nFerns: ${document.querySelector('#ferns').value} small plants (check mature sizes)\nCeramic deer: ${deer.visible?document.querySelector('#position-value').textContent:'Not included'}\n\nMaterials: glass jar, small pebbles, suitable terrarium soil, moss, small ferns${deer.visible?', ivory ceramic deer':''}.\n\nLayer pebbles and soil, plant ferns at the back, tuck moss around the plants, and leave a small clearing for the deer. Dimensions and quantities are visual planning estimates.\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));download(url,'nans-terrarium-plan.txt');setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your birthday design notes are saved.')};
function resize(){const r=canvas.parentElement.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(canvas.parentElement);resize();document.querySelector('#loading').remove();renderer.setAnimationLoop(()=>{controls.update();renderer.render(scene,camera)});
